 "content": "from collections import Counter, deque


def transform(grid):
    """Fill background-colored enclosed regions with color 4."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            component = []
            touches_edge = False
            while queue:
                y, x = queue.popleft()
                component.append((y, x))
                if y == 0 or y == h - 1 or x == 0 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == background and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        queue.append((ny, nx))
            if not touches_edge:
                for y, x in component:
                    out[y][x] = 4
    return out
